cat > /app/solution.sparql << 'EOF'
PREFIX uni: <http://university.org/ontology/>

SELECT ?professorName (GROUP_CONCAT(DISTINCT ?country; separator=", ") AS ?countries)
WHERE {
  ?prof a uni:Person .
  ?prof uni:hasName ?professorName .
  ?prof uni:role ?role .
  FILTER (REGEX(?role, "Professor") && !REGEX(?role, "Assistant"))

  # At least one department in EU country (as of 2025-08-16)
  FILTER EXISTS {
    ?prof uni:worksIn ?deptEU .
    ?deptEU uni:belongsTo ?uniEU .
    ?uniEU uni:locatedInCountry ?euCountry .
    VALUES ?euCountry {
      "AT" "BE" "BG" "CY" "CZ" "DE" "DK" "EE" "ES" "FI" "FR" "GR" "HR" "HU"
      "IE" "IT" "LT" "LU" "LV" "MT" "NL" "PL" "PT" "RO" "SE" "SI" "SK"
    }
  }

  # At least one department with >10 students enrolled in classes taught in that department
  FILTER EXISTS {
    ?prof uni:worksIn ?deptBig .
    {
      SELECT ?deptBig (COUNT(DISTINCT ?student) AS ?studentCount)
      WHERE {
        ?prof2 uni:worksIn ?deptBig .
        ?prof2 uni:teaches ?class .
        ?student uni:isEnrolledIn ?class .
      }
      GROUP BY ?deptBig
    }
    FILTER (?studentCount > 10)
  }

  # Now get all countries where the professor works
  ?prof uni:worksIn ?deptAll .
  ?deptAll uni:belongsTo ?uniAll .
  ?uniAll uni:locatedInCountry ?country .
}
GROUP BY ?professorName
EOF
